def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the horizontal color key repeated across three consecutive rows.
    seq = None
    for r in range(h - 2):
        for c in range(w):
            if grid[r][c] == 0 or not (grid[r][c] == grid[r+1][c] == grid[r+2][c]):
                continue
            end = c
            while end < w and grid[r][end] != 0 and grid[r][end] == grid[r+1][end] == grid[r+2][end]:
                end += 1
            if end - c >= 3:
                seq = grid[r][c:end]
                break
        if seq:
            break
    if not seq or 1 not in seq:
        return [row[:] for row in grid]

    # Select the largest 4-connected component of color 1 as the shape.
    seen, components = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r, c) in seen:
                continue
            q, comp = deque([(r, c)]), []
            seen.add((r, c))
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1 and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            components.append(comp)
    shape_pts = max(components, key=len)
    r0 = min(r for r,c in shape_pts)
    c0 = min(c for r,c in shape_pts)
    r1 = max(r for r,c in shape_pts)
    shape = [(r-r0,c-c0) for r,c in shape_pts]
    shape_h = r1-r0+1
    idx = seq.index(1)
    first_top = r0 - idx*shape_h
    out = [[0]*w for _ in range(h)]
    for i, color in enumerate(seq):
        top = first_top + i*shape_h
        for dr, dc in shape:
            rr, cc = top+dr, c0+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
